        RailwayWorld.Node activeDestination = train.destination;

        click(game, 60, 337);
        click(game, 692, 576);
        click(game, 1080, 576);
        click(game, 562, 378);
        assertEquals(5, train.stops.size());

        click(game, 157, 657);
