        @Test void demolitionRefundsUnusedObjectsAndProtectsAssetsInUse() {
        RailwayWorld world = new RailwayWorld();
        RailwayWorld.Train firstTrain = world.trains.get(0);
        int startingCash = world.cash;

        assertEquals(RailwayWorld.DemolitionResult.TRACK_IN_USE,
            world.demolishAt(new RailwayWorld.Node(350, 440), 2));
        assertEquals(RailwayWorld.DemolitionResult.STATION_IN_USE,
            world.demolishAt(new RailwayWorld.Node(175, 440), 2));

        RailwayWorld.Node sidingPosition = new RailwayWorld.Node(1800, 1500);
        RailwayWorld.Station siding = world.buildStation(sidingPosition);
        assertNotNull(siding);
        assertEquals(RailwayWorld.DemolitionResult.STATION_REMOVED,
            world.demolishAt(sidingPosition, 2));
        assertFalse(world.stations.contains(siding));
        assertEquals(startingCash - RailwayWorld.STATION_COST + RailwayWorld.STATION_COST / 2, world.cash);

        RailwayWorld.Node lineStart = new RailwayWorld.Node(1800, 1500);
        RailwayWorld.Node lineEnd = new RailwayWorld.Node(2000, 1500);
        assertTrue(world.buildTrack(lineStart, lineEnd));
        RailwayWorld.Node signal = new RailwayWorld.Node(1900, 1500);
        assertTrue(world.toggleSignal(signal));
        assertEquals(RailwayWorld.DemolitionResult.SIGNAL_REMOVED, world.demolishAt(signal, 2));
        assertFalse(world.signals.contains(signal));
        assertEquals(RailwayWorld.DemolitionResult.TRACK_REMOVED, world.demolishAt(signal, 2));

        RailwayWorld.Train secondTrain = world.deployTrain(new RailwayWorld.Node(400, 440));
        assertNotNull(secondTrain);
        assertEquals(RailwayWorld.DemolitionResult.TRAIN_CARRYING_CARGO,
            world.demolishTrain(firstTrain));
        assertEquals(RailwayWorld.DemolitionResult.TRAIN_REMOVED, world.demolishTrain(secondTrain));
        assertEquals(RailwayWorld.DemolitionResult.LAST_TRAIN, world.demolishTrain(firstTrain));
        }

