    @Test void oneShotScheduleStopsAfterItsLastStation() {
        RailwayWorld world = new RailwayWorld();
        RailwayWorld.Train train = world.trains.get(0);

        assertTrue(world.addScheduleStop(train, world.stations.get(1)));
        assertTrue(world.addScheduleStop(train, world.stations.get(3)));
        assertTrue(world.addScheduleStop(train, world.stations.get(4)));
        assertTrue(world.moveScheduleStop(train, 4, -1));
        assertEquals(new RailwayWorld.Node(1325, 760), train.stops.get(3));
        assertEquals(new RailwayWorld.Node(1010, 440), train.destination);
        assertTrue(world.removeScheduleStop(train, 0));
        assertEquals(new RailwayWorld.Node(1010, 440), train.destination);
        world.setScheduleLoop(train, false);

        world.advanceTicks(550);

        assertFalse(train.looping);
        assertTrue(train.path.isEmpty());
        assertEquals(new RailwayWorld.Node(700, 760), train.position);
    }

