    @Test void carriagesFollowRailThroughAStationCorner() {
        RailwayWorld world = new RailwayWorld();
        RailwayWorld.Train train = world.trains.get(0);
        assertTrue(world.addScheduleStop(train, world.stations.get(3)));
        assertTrue(world.moveScheduleStop(train, 1, 1));

        world.advanceTicks(102);

        assertEquals(new RailwayWorld.Node(1010, 440), train.position);
        assertEquals(new RailwayWorld.Node(700, 760), train.destination);
        RailwayGamePanel renderer = new App().createGamePanel();
        for (int index = 1; index <= train.carriages; index++) {
            double[] carriage = renderer.carriagePosition(train, index);
            assertTrue(distanceFromRail(world, carriage[0], carriage[1]) < 0.0001,
                    "carriage " + index + " should stay on a rail at the station turn");
        }

        world.advanceTicks(10);
        for (int index = 1; index <= train.carriages; index++) {
            double[] carriage = renderer.carriagePosition(train, index);
            assertTrue(distanceFromRail(world, carriage[0], carriage[1]) < 0.0001,
                    "carriage " + index + " should follow the curved route");
        }
    }

    @Test void saveRestoresMovingTrainsContractsAndMapView(@TempDir Path tempDirectory)
            throws java.io.IOException {
        RailwayWorld world = new RailwayWorld();
        RailwayWorld.Train train = world.trains.get(0);
        RailwayWorld.Contract contract = world.contracts.get(1);
        assertTrue(world.acceptContract(contract));
        assertTrue(world.addScheduleStop(train, world.stations.get(3)));
        assertTrue(world.addCarriage(train));
        world.setScheduleLoop(train, false);
        world.advanceTicks(17);
        RailwayWorld.ViewState view = new RailwayWorld.ViewState(420.5, 180.25, 0.74,
                train.id, contract.id, false, true);
        Path savePath = tempDirectory.resolve("railway.lmsave");

        world.save(savePath, view);
        RailwayWorld.LoadedGame loaded = RailwayWorld.load(savePath);
        RailwayWorld restored = loaded.world();
        RailwayWorld.Train restoredTrain = restored.trains.get(0);

        assertEquals(world.cash, restored.cash);
        assertEquals(world.day, restored.day);
        assertEquals(world.minutes, restored.minutes);
        assertEquals(world.tracks, restored.tracks);
        assertEquals(train.stops, restoredTrain.stops);
        assertEquals(train.railTrail, restoredTrain.railTrail);
        assertEquals(train.positionAt(), restoredTrain.positionAt());
        assertEquals(train.load(), restoredTrain.load());
        assertSame(restored.contracts.get(0), restoredTrain.cargo.get(0).contract());
        assertEquals(RailwayWorld.ContractState.ACCEPTED, restored.contracts.get(1).state);
        assertEquals(view, loaded.view());

        world.advanceTicks(20);
        restored.advanceTicks(20);
        assertEquals(train.positionAt(), restoredTrain.positionAt());
        assertEquals(world.cash, restored.cash);
    }

        @Test void startupRestoresTheRememberedSave(@TempDir Path tempDirectory)
            throws java.io.IOException, java.util.prefs.BackingStoreException {
        RailwayWorld savedWorld = new RailwayWorld();
        savedWorld.cash += 250;
        RailwayWorld.Train savedTrain = savedWorld.trains.get(0);
        Path savePath = tempDirectory.resolve("last-railway.lmsave");
        savedWorld.save(savePath, new RailwayWorld.ViewState(0, 0, 0.62,
                savedTrain.id, savedWorld.contracts.get(0).id, true, false));

        Preferences preferences = Preferences.userNodeForPackage(App.class);
        String previousPath = preferences.get("lastSavePath", null);
        try {
            preferences.put("lastSavePath", savePath.toString());
            RailwayGamePanel game = new App().createGamePanel();

            game.restoreLastSavedGame();

            assertEquals(savedWorld.cash, game.world.cash);
            assertEquals(savedWorld.tracks, game.world.tracks);
            assertEquals(RailwayGamePanel.Tool.CURSOR, game.currentTool());
        } finally {
            if (previousPath == null) {
                preferences.remove("lastSavePath");
            } else {
                preferences.put("lastSavePath", previousPath);
            }
            preferences.flush();
        }
    }

